import React, { useState } from 'react';
import { Navigation, AlertCircle, Database, CheckCircle2, Clock, MapPin } from 'lucide-react';

const ScheduleTab = ({ onViewReport }) => {
  const [verifyingId, setVerifyingId] = useState(null);

  const schedule = [
    { id: 'LOC_04', time: '08:00', area: 'Sector 4', hasReport: true, status: 'pending', type: 'Biohazard' },
    { id: 'LOC_09', time: '10:30', area: 'Zone B', hasReport: false, status: 'pending', type: 'General' },
    { id: 'LOC_12', time: '13:00', area: 'Plaza SQ', hasReport: false, status: 'done', type: 'Recycle' },
    { id: 'LOC_15', time: '15:30', area: 'East Gate', hasReport: true, status: 'pending', type: 'General' },
    { id: 'LOC_22', time: '17:00', area: 'North Hub', hasReport: false, status: 'pending', type: 'Biohazard' },
    { id: 'LOC_31', time: '19:00', area: 'South Park', hasReport: false, status: 'pending', type: 'Recycle' },
  ];

  const handleRouteClick = (area) => {
    alert(`🛰️ GPS SYNC: Calculating fastest route to ${area}...`);
  };

  return (
    <div className="w-full max-w-md h-full flex flex-col">
      {/* SCROLLABLE LIST AREA */}
      <div className="flex-1 overflow-y-auto no-scrollbar pb-20">
        <div className="relative border-l-4 border-[#47510B]/10 ml-4 pl-8 space-y-10">
          {schedule.map((item) => (
            <div key={item.id} className="relative">
              {/* Timeline Node */}
              <div className={`absolute -left-[42px] top-1 w-6 h-6 rounded-full border-4 border-[#FDFAD8] z-10 transition-colors ${item.status === 'done' ? 'bg-[#CAD23C]' : 'bg-[#47510B]'}`} />

              <div className="group relative">
                <div className="flex items-center gap-3 mb-2">
                  <Clock size={12} className="text-[#47510B]/40" />
                  <span className="text-[10px] font-black text-[#47510B]/40 uppercase tracking-widest">{item.time}</span>

                  {/* CLICKING THIS NOW OPENS THE SPECIFIC MODAL */}
                  {item.hasReport && (
                    <button 
                      onClick={() => onViewReport(item.id)}
                      className="flex items-center gap-1 bg-[#AB1717] text-white px-2 py-0.5 rounded text-[8px] font-black animate-pulse shadow-md hover:scale-105 transition-transform"
                    >
                      <AlertCircle size={10} /> ISSUE_REPORTED
                    </button>
                  )}
                </div>

                <div className={`p-5 rounded-[30px] border-2 transition-all duration-300 flex items-center justify-between ${item.status === 'done' ? 'bg-white/40 border-dashed border-[#47510B]/10' : 'bg-white border-[#47510B] shadow-[6px_6px_0_0_#47510B]'}`}>
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                        <MapPin size={14} className={item.status === 'done' ? 'opacity-20' : 'text-[#CAD23C]'} />
                        <h4 className={`text-xl font-black uppercase italic leading-none ${item.status === 'done' ? 'opacity-20' : 'text-[#47510B]'}`}>{item.area}</h4>
                    </div>
                    <p className="text-[9px] font-bold opacity-30 mt-2 uppercase tracking-tighter">{item.type} // {item.id}</p>
                  </div>

                  <div className="flex gap-2">
                    <button 
                      onClick={() => setVerifyingId(item.id)} 
                      className="p-3 rounded-xl bg-[#FDFAD8] text-[#47510B] border border-[#47510B]/10 hover:bg-[#CAD23C]"
                    >
                      <CheckCircle2 size={20} strokeWidth={2.5} />
                    </button>
                    <button 
                      onClick={() => handleRouteClick(item.area)} 
                      className="p-3 rounded-xl bg-[#47510B] text-[#CAD23C] shadow-lg active:scale-90"
                    >
                      <Navigation size={20} strokeWidth={3} />
                    </button>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* ADMIN VERIFICATION MODAL (For Tasks) */}
      {verifyingId && (
         <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-[#47510B]/95 backdrop-blur-md">
           <div className="bg-[#FDFAD8] p-8 rounded-[50px] border-[10px] border-white w-full max-w-sm text-center">
             <Database size={40} className="mx-auto text-[#47510B] mb-4 animate-bounce" />
             <h3 className="text-xl font-black uppercase italic text-[#47510B]">Admin_Sensor_Sync</h3>
             <button onClick={() => setVerifyingId(null)} className="w-full py-5 bg-[#47510B] text-[#CAD23C] rounded-[25px] font-black uppercase text-sm mt-6">
                Confirm Completion
             </button>
           </div>
         </div>
      )}
    </div>
  );
};

export default ScheduleTab;
